package com.smarthire.entity;
import com.smarthire.enums.JobType; import com.smarthire.enums.WorkMode; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="jobs") public class Job {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false) private Long recruiterId; @Column(nullable=false) private String title; @Column(nullable=false) private String companyName; private String location; @Enumerated(EnumType.STRING) private JobType jobType; @Enumerated(EnumType.STRING) private WorkMode workMode; @Column(nullable=false,length=5000) private String description; @Column(length=5000) private String requirements; private String salaryRange; private boolean active=true; private Instant createdAt=Instant.now(); private Instant updatedAt=Instant.now(); protected Job(){} public Job(Long recruiterId,String title,String companyName,String location,JobType jobType,WorkMode workMode,String description,String requirements,String salaryRange){this.recruiterId=recruiterId; update(title,companyName,location,jobType,workMode,description,requirements,salaryRange);} public void update(String title,String companyName,String location,JobType jobType,WorkMode workMode,String description,String requirements,String salaryRange){this.title=title;this.companyName=companyName;this.location=location;this.jobType=jobType;this.workMode=workMode;this.description=description;this.requirements=requirements;this.salaryRange=salaryRange;this.updatedAt=Instant.now();} public void deactivate(){active=false;updatedAt=Instant.now();} public Long getId(){return id;} public Long getRecruiterId(){return recruiterId;} public String getTitle(){return title;} public String getCompanyName(){return companyName;} public String getLocation(){return location;} public JobType getJobType(){return jobType;} public WorkMode getWorkMode(){return workMode;} public String getDescription(){return description;} public String getRequirements(){return requirements;} public String getSalaryRange(){return salaryRange;} public boolean isActive(){return active;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;}
}
